from common import *
B = Bank()
STRATS = ["Leverage existing assets", "Reconfigure the value chain", "Create a market niche"]

# ---------------- S18-01 economies of scale ----------------
lo = "S18-01"
B.mc(lo, [lo], "concept", "Economies of scale exist when:", ["Long-run average costs decline as output is increased", "Unit costs decline as cumulative production increases", "Producing two products together costs less than producing them separately", "A product becomes more valuable as more people use it"], 0,
     "That is the professor's definition. Falling cost with cumulative production is a learning curve, joint production is economies of scope, and value rising with users is network effects.")
B.mc(lo, [lo], "concept", "Diseconomies of scale exist when:", ["Long-run average costs rise as output increases", "Long-run average costs fall as output increases", "Marginal cost is zero", "A firm produces several products"], 0, "Past the lowest point of the long-run average cost curve, average cost rises: diseconomies of scale.")
B.tf(lo, [lo, "S18-09"], "concept", "True or false: Economies of scale are a barrier to entry because a small entrant has a higher average cost than a large incumbent.", True, "True. The entrant spreads its fixed costs over fewer units.")
B.mc(lo, [lo], "concept", "In Figure 8-11 (S18 slides p. 31), why would a second firm not enter?", ["Splitting the market leaves each firm at an average cost above the price", "The incumbent's price is below marginal cost", "The second firm would face network effects", "The market is protected by a patent"], 0,
     "One firm at \\(Q^M\\) has \\(ATC(Q^M)\\) below \\(P^M\\). Two firms at \\(Q^M/2\\) each have \\(ATC(Q^M/2)\\) above the price, so both would lose money.")
B.tf(lo, [lo, "S18-02"], "concept", "True or false: Economies of scale depend on cumulative output over the firm's history.", False, "False. Scale depends on output per period. Cumulative output is the learning curve.")
B.mc(lo, [lo], "concept", "The S18 slides show high-voltage power lines under economies of scale. What is the point?", ["A utility's network costs so much that one firm can serve a region more cheaply than two", "Power is a commodity with no brand", "Electricity prices are regulated below cost", "Utilities have strong network effects among customers"], 0,
     "The huge fixed cost of the grid means average cost keeps falling with output, so a second network would raise average cost for everyone.")
B.num(lo, [lo], "A firm's total cost is TC = 10,000 + 5Q. What is its average total cost at Q = 100?", 105, "ATC = TC/Q = (10,000 + 500)/100 = 105. Or F/Q + c = 100 + 5.", {"f": "ac", "F": 10000, "c": 5, "Q": 100}, unit="$")
B.num(lo, [lo], "Same firm (TC = 10,000 + 5Q). What is ATC at Q = 1,000?", 15, "ATC = 10,000/1,000 + 5 = 10 + 5 = $15. Average cost fell from $105 to $15: economies of scale.", {"f": "ac", "F": 10000, "c": 5, "Q": 1000}, unit="$")
B.num(lo, [lo], "A streaming service spends $600 million per year on content and technology plus $2 per subscriber per year. With 50 million subscribers, what is its average cost per subscriber?", 14,
      "ATC = 600/50 + 2 = 12 + 2 = $14 per subscriber per year.", {"f": "ac", "F": 600, "c": 2, "Q": 50}, unit="$")
B.num(lo, [lo], "Same streaming cost structure ($600 million fixed plus $2 per subscriber). An entrant expects 5 million subscribers. How much higher is its average cost than the incumbent's at 50 million?", 108,
      "Entrant: 600/5 + 2 = $122. Incumbent: 600/50 + 2 = $14. Difference: $108 per subscriber.", {"f": "ac_gap", "F": 600, "c": 2, "Q1": 5, "Q2": 50}, unit="$")
B.num(lo, [lo, "S18-09"], "Meta's 2021 Q4 total operating expenses were $21,086 million on total revenue of $33,671 million. What percent of revenue were operating expenses? Answer in percent.", 62.62,
      "21,086 / 33,671 = 0.626, or about 62.6%. Twitter's ratio was about 89% and Snapchat's about 81% in 2021 (from the exercise). Spreading costs over far more users helps Meta.", {"f": "pct", "num": 21086, "den": 33671}, unit="%")
B.mc(lo, [lo], "apply", "A grocery chain negotiates lower prices from suppliers because it buys in enormous volume, so its cost per item falls as it grows. Which concept is this?", ["Economies of scale", "Learning curve", "Economies of scope", "Network effects"], 0,
     "Cost per unit falls with the SIZE of output (volume purchasing). Not experience over time, not different products together, not user value.")
B.mc(lo, [lo, "S18-09"], "apply", "A small town has one hardware store that barely breaks even. A chain considers opening a second store there. What barrier is it most likely facing?", ["Economies of scale relative to the size of the market", "Network effects", "Patents", "Predatory pricing"], 0,
     "Like the abandoned truck stop on slide p. 30: the market is too small for two stores to each reach a low average cost.")
B.mc(lo, [lo], "apply", "In the Barriers to Entry exercise, Meta's cost of revenue (data centers, servers, network) was about 19% of sales versus about 33% for Twitter and 34% for Snapchat in 2021 Q4. Which concept best explains Meta's lower share?", ["Economies of scale", "Penetration pricing", "Limit pricing", "Economies of scope"], 0,
     "These are largely fixed infrastructure costs spread over about 2 billion daily users: average cost per user falls with size.")

# ---------------- S18-02 learning curves ----------------
lo = "S18-02"
B.mc(lo, [lo], "concept", "On a learning curve, what is on the horizontal axis?", ["Cumulative production", "Output per period", "Number of workers", "Price"], 0,
     "Experience = cumulative production (slide p. 32). Output per period is what economies of scale depend on.")
B.mc(lo, [lo], "concept", "A learning curve shows that:", ["Cost per unit declines as cumulative production increases", "Average cost declines as output per period increases", "Output rises as more workers are hired", "Users value a product more as more people use it"], 0,
     "Learning = declining costs per unit; experience = cumulative production.")
B.tf(lo, [lo], "concept", "True or false: An 80% learning curve means unit cost falls by 80% each time cumulative output doubles.", False,
     "False. It falls TO 80% of its old level, a 20% drop, with each doubling.")
B.mc(lo, [lo], "concept", "Which strategic implication of learning curves appears on the S18 slides?", ["Firms may price aggressively to descend the learning curve faster", "Firms should produce less to keep costs low", "Learning curves make predatory pricing legal", "Learning curves eliminate the need for economies of scale"], 0,
     "Selling more now builds cumulative output faster, which lowers future costs (slide p. 34).")
B.mc(lo, [lo], "concept", "Three learning curves start at the same cost. Which is the weakest barrier to entry?", ["One that drops almost all the way in the first few units and then goes flat", "One that keeps falling over a long range of cumulative output", "One where the incumbent is far down a long curve", "One where knowledge cannot leak to rivals"], 0,
     "If nearly all the learning happens in the first few units, an entrant gets there quickly too, so the incumbent's lead is short.")
B.num(lo, [lo], "The first unit costs $1,000 and the firm is on an 80% learning curve. What does the 8th unit cost?", 512,
      "Unit 8 is 3 doublings (1, 2, 4, 8). \\(1{,}000 \\times 0.8^3 = 512\\).", {"f": "learn", "C1": 1000, "rate": 0.8, "n": 8}, unit="$")
B.num(lo, [lo], "The first unit costs $500 on a 90% learning curve. What does the 4th unit cost?", 405,
      "2 doublings. \\(500 \\times 0.9^2 = 500 \\times 0.81 = 405\\).", {"f": "learn", "C1": 500, "rate": 0.9, "n": 4}, unit="$")
B.num(lo, [lo], "The Model T cost curve on the slides is \\(y = 87{,}244x^{-0.317}\\). By what factor does unit cost change each time cumulative production doubles? Round to 2 decimals.", 0.8,
      "\\(2^{-0.317} = 0.80\\): about an 80% learning curve, a 20% drop per doubling.", {"f": "pow", "base": 2, "exp": -0.317}, tol=0.02)
B.num(lo, [lo], "The 100th unit costs $200 on an 85% learning curve. What does the 400th unit cost?", 144.5,
      "100 to 200 to 400 is 2 doublings. \\(200 \\times 0.85^2 = 200 \\times 0.7225 = 144.50\\).", {"f": "learn_from", "C": 200, "rate": 0.85, "k": 2}, unit="$")
B.mc(lo, [lo], "apply", "A solar panel maker's cost per panel fell 20% each time its total panels ever produced doubled. A rival hires away several of its process engineers. What happens to its learning-curve barrier?", ["It weakens, because knowledge spills over to the rival", "It strengthens, because the rival now has higher costs", "Nothing changes; learning is about cumulative output only", "It turns into economies of scale"], 0,
     "Learning effects are a barrier only if there is no knowledge spillover or leakage (slide p. 34, Quiz 8 Q2).")
B.mc(lo, [lo, "S18-01"], "apply", "A shipyard's cost per ship fell from $90 million on its 1st ship to $60 million on its 20th, even though it builds only two ships a year. Which concept explains this?", ["Learning curve", "Economies of scale", "Economies of scope", "Network effects"], 0,
     "Output per year did not grow; cumulative experience did. That is the learning curve, not scale.")
B.mc(lo, [lo, "S18-07"], "apply", "A chip maker cuts prices on a new memory chip below its current unit cost to sell huge volumes in its first year. Which reason fits the S18 slides?", ["Descend the learning curve faster to lower future costs", "Predatory pricing to drive out an existing rival", "Penetration pricing to build network effects", "Limit pricing, since the price is above cost"], 0,
     "Slide p. 34: firms may price aggressively to move down the learning curve faster. No rival or network is mentioned.")

# ---------------- S18-03 economies of scope ----------------
lo = "S18-03"
B.mc(lo, [lo], "concept", "Economies of scope exist when:", ["Producing two products together costs less than producing them separately", "Average cost falls as output of one product rises", "Unit cost falls with cumulative output", "A product is worth more as more people use it"], 0,
     "Scope = different products together. Falling AC with output is scale; cumulative output is learning; user value is network effects.")
B.mc(lo, [lo], "concept", "Which inequality defines economies of scope?", ["\\(C(Q_1, 0) + C(0, Q_2) > C(Q_1, Q_2)\\)", "\\(C(Q_1, 0) + C(0, Q_2) < C(Q_1, Q_2)\\)", "\\(C(2Q) < 2C(Q)\\)", "\\(ATC(Q_1) > ATC(Q_2)\\)"], 0,
     "Separate production costs more than joint production. \\(C(2Q) < 2C(Q)\\) describes scale, not scope.")
B.tf(lo, [lo, "S18-01"], "concept", "True or false: Economies of scope and economies of scale are the same idea.", False, "False. Scale: more of the same product. Scope: different products together.")
B.tf(lo, [lo, "S18-09"], "concept", "True or false: Economies of scope can be a barrier to entry because a single-product entrant pays costs that a multi-product incumbent shares across products.", True, "True. The incumbent's shared assets lower its cost of each product.")
B.mc(lo, [lo, "S18-10"], "concept", "Which of the reading's entry strategies relies most directly on economies of scope?", ["Leverage existing assets", "Reconfigure the value chain", "Create a market niche", "Directly attack the market leader"], 0,
     "Using shelf space, locations, brand or idle capacity you already have for a new product is sharing assets across products.")
B.mc(lo, [lo], "concept", "Economies of scope come from:", ["Sharing inputs such as a brand, plant, distribution network or customer data across products", "Producing more units of one product", "Accumulating experience over time", "Charging lower prices than rivals"], 0, "Shared inputs are the source of scope savings.")
B.num(lo, [lo], "Making 1,000 phones alone costs $300,000. Making 1,000 tablets alone costs $200,000. Making both together costs $420,000. How much does joint production save?", 80000,
      "Separate: 300,000 + 200,000 = 500,000. Together: 420,000. Savings: $80,000, so there are economies of scope.", {"f": "scope", "c1": 300000, "c2": 200000, "c12": 420000}, unit="$", kind="calc")
B.num(lo, [lo], "A bank's checking business alone costs $50 million and its credit card business alone costs $30 million. Run together, they cost $85 million. How much does joint production save? (Use a negative number if it costs more.)", -5000000,
      "Separate: 50 + 30 = $80 million. Together: $85 million. Savings = 80 - 85 = -$5 million: diseconomies of scope; they are cheaper apart.", {"f": "scope", "c1": 50000000, "c2": 30000000, "c12": 85000000}, unit="$", kind="calc")
B.num(lo, [lo], "A bakery spends $40,000 a year making bread alone and $25,000 making pastries alone. Using the same ovens and staff for both costs $52,000. What percent of the separate total is saved? Answer in percent.", 20,
      "Separate: $65,000. Savings: 65,000 - 52,000 = $13,000. 13,000 / 65,000 = 20%.", {"f": "scope_pct", "c1": 40000, "c2": 25000, "c12": 52000}, unit="%", kind="calc")
B.num(lo, [lo], "A firm makes widgets for $120,000 and gadgets for $80,000 separately. What is the most a combined plant could cost and still show economies of scope?", 200000,
      "Economies of scope require joint cost below the separate total: below 120,000 + 80,000 = $200,000.", {"f": "add", "a": 120000, "b": 80000}, unit="$", kind="calc")
B.mc(lo, [lo], "apply", "Amazon uses the warehouses and delivery fleet it built for retail to also deliver groceries. Which concept is this?", ["Economies of scope", "Economies of scale", "Learning curve", "Limit pricing"], 0,
     "Different products share the same distribution assets: scope.")
B.mc(lo, [lo], "apply", "Costco opened Costco Home stores near its warehouses and let its existing members shop there. In cost terms, what is Costco exploiting?", ["Economies of scope from sharing its brand and member base", "Economies of scale in furniture", "A learning curve in furniture", "Predatory pricing against furniture stores"], 0,
     "The same brand and customer base serve two businesses. The reading calls this leveraging existing assets.")
B.mc(lo, [lo], "apply", "Meta runs Facebook, Instagram, WhatsApp and Messenger on shared data centers and an ad system. A new single-app competitor must build all of that for one app. Which advantage does Meta have?", ["Economies of scope", "Penetration pricing", "Limit pricing", "Second-mover advantage"], 0,
     "Shared infrastructure across several products lowers the cost of each one.")
B.mc(lo, [lo, "S18-01"], "apply", "A car maker cuts its cost per car by building 2 million cars a year instead of 500,000 of the same model. Which concept is this, and which is it NOT?", ["Economies of scale, not scope", "Economies of scope, not scale", "A learning curve, not scale", "Network effects, not scale"], 0,
     "More of the SAME product per year: scale. Scope would need different products sharing inputs.")
B.mc(lo, [lo], "apply", "Disney uses the same characters in movies, theme parks, toys and streaming. Why does this lower its costs compared with separate firms?", ["The character development cost is shared across many products", "It produces more of each product", "Its theme park staff have more experience", "Customers value the parks more when more people visit"], 0,
     "Creating a character once and using it in many businesses is a shared input: economies of scope.")

# ---------------- S18-04 network effects ----------------
lo = "S18-04"
B.mc(lo, [lo], "concept", "Network effects exist when:", ["A product becomes more valuable to each user as more people use it", "Average cost falls as output rises", "Cost per unit falls with cumulative output", "Producing two products together lowers cost"], 0, "Value to users rises with the number of users.")
B.tf(lo, [lo], "concept", "True or false: A new platform with a better product can easily beat an incumbent platform with strong network effects.", False,
     "False. Users are locked in: switching alone gains nothing, so a better product with few users is worth less to each user.")
B.mc(lo, [lo], "concept", "What is critical mass in a network market?", ["The number of users needed before the network keeps growing on its own", "The largest number of users a network can serve", "The output at which average cost is lowest", "The number of firms a market can support"], 0, "Below critical mass the network stalls; above it, it is attractive enough to keep adding users.")
B.mc(lo, [lo, "S18-09"], "concept", "KSL Classifieds beat Craigslist in Utah (S18 slides p. 39). Which barrier protected KSL once it had the local buyers and sellers?", ["Network effects", "Economies of scope", "Patents", "Learning curve"], 0, "Buyers go where sellers are and sellers go where buyers are.")
B.tf(lo, [lo], "concept", "True or false: In a two-way network, adding one more user benefits the users already on the network.", True, "True. A new user adds 2n connections; every existing user can now reach one more person.")
B.num(lo, [lo], "A two-way messaging network has 50 users. How many potential connections does it have?", 2450,
      "\\(n(n-1) = 50 \\times 49 = 2{,}450\\) (textbook Module 4).", {"f": "conn", "n": 50}, unit="connections")
B.num(lo, [lo], "A two-way network has 100 users. How many new connections does the 101st user add?", 200,
      "A new user adds \\(2n = 2 \\times 100 = 200\\). Check: \\(101 \\times 100 - 100 \\times 99 = 10{,}100 - 9{,}900 = 200\\).", {"f": "add_conn", "n": 100}, unit="connections")
B.num(lo, [lo], "In 2022 Q2 Twitter had 237.8 million daily users and $1,076 million of advertising revenue. What was its ad revenue per user?", 4.52,
      "1,076 / 237.8 = $4.52 per user for the quarter, versus $14.29 for Meta.", {"f": "ratio", "num": 1076.003, "den": 237.8}, unit="$")
B.num(lo, [lo], "In 2022 Q2 Snapchat had 347 million daily users, $1,111 million of revenue and $1,512 million of operating expense. What was its profit per user? (Negative for a loss.)", -1.16,
      "Revenue per user = 1,110.9 / 347 = $3.20. Cost per user = 1,511.8 / 347 = $4.36. Profit per user = 3.20 - 4.36 = -$1.16.", {"f": "profit_per", "rev": 1110.909, "cost": 1511.849, "users": 347}, unit="$")
B.mc(lo, [lo], "apply", "Using the exercise data, why did Meta earn about three times Twitter's ad revenue per user in 2022?", ["Network effects: more users and data make each ad more valuable to advertisers", "Meta charged users a subscription fee", "Meta spent less on R&D", "Twitter used limit pricing"], 0,
     "More users and engagement mean more data for targeting and more reach for advertisers, so each user brings in more ad revenue.")
B.mc(lo, [lo, "S18-01"], "apply", "Which pair best matches the exercise's conclusion about Meta's advantages?", ["Revenue advantage from network effects; cost advantage from economies of scale", "Revenue advantage from economies of scale; cost advantage from network effects", "Both from patents", "Both from limit pricing"], 0,
     "Network effects raise what each user is worth to advertisers; scale spreads mostly fixed infrastructure over more users.")

# ---------------- S18-05 limit pricing ----------------
lo = "S18-05"
B.mc(lo, [lo], "concept", "Limit pricing is:", ["An incumbent keeping its price below the monopoly level to prevent entry", "A firm temporarily pricing below marginal cost to drive rivals out", "A low initial price to gain a critical mass of customers", "Pricing at the monopoly level to maximize profit"], 0, "Slide p. 41. The second is predatory pricing; the third is penetration pricing.")
B.mc(lo, [lo, "S18-06"], "concept", "Who is the target of limit pricing?", ["Potential entrants not yet in the market", "A rival already in the market", "Price-sensitive customers", "Suppliers"], 0, "Slide p. 46: limit pricing targets potential entrants, before entry.")
B.tf(lo, [lo, "S18-06"], "concept", "True or false: Under limit pricing the incumbent's price is usually still above its own cost, so it keeps earning a profit.", True, "True. Profit is lower than monopoly profit but still positive (slide p. 46).")
B.tf(lo, [lo], "concept", "True or false: Limit pricing is generally illegal under the Sherman Act.", False, "False. It is generally legal; it is just a low price. Predatory pricing is the one that can violate Sherman Act §2.")
B.mc(lo, [lo], "concept", "In Figure M1-2, why does the entrant stay out when the incumbent produces \\(Q^L\\)?", ["Its residual demand lies below its average cost at every output", "The incumbent's price is below marginal cost", "The entrant has a patent problem", "The entrant's demand is perfectly elastic"], 0,
     "Residual demand = market demand minus \\(Q^L\\). If it never reaches the entrant's AC, no output earns a profit.")
B.mc(lo, [lo], "concept", "According to the textbook, why might a low pre-entry price fail to deter a fully informed entrant?", ["The entrant cares about the price after it enters, and the incumbent may not keep it low", "Low prices always attract more entrants", "Entrants never look at prices", "Limit prices are always above the monopoly price"], 0,
     "Without a commitment, learning-curve advantage, signaling or reputation linking today's price to post-entry profits, the threat is not credible.")
B.mc(lo, [lo], "apply", "Before a big airline's route is entered by a low-cost carrier, the airline cuts fares on that route even though it is still profitable. This is best described as:", ["Limit pricing", "Predatory pricing", "Penetration pricing", "Economies of scale"], 0,
     "The rival has not entered yet and the price is still above cost: limit pricing (the slides' airline example on p. 42).")
B.mc(lo, [lo], "apply", "An incumbent's monopoly price is $50 and its cost is $20. An entrant's lowest average cost would be $35. Which price deters entry while keeping the incumbent profitable?", ["$32", "$50", "$15", "$40"], 0,
     "The price must be below the entrant's $35 AC (so entry is unprofitable) and above the incumbent's $20 cost. $15 is below the incumbent's own cost.")

# ---------------- S18-06 predatory pricing ----------------
lo = "S18-06"
B.mc(lo, [lo], "concept", "Predatory pricing is:", ["A firm temporarily pricing below marginal cost to drive competitors out of the market", "An incumbent keeping price below the monopoly level to prevent entry", "A low initial price to build a critical mass of customers", "Charging different prices to different customers"], 0, "Slide p. 41 definition.")
B.mc(lo, [lo], "concept", "What is the usual legal test for the 'below cost' part of a predatory pricing case?", ["Price below average variable cost", "Price below average total cost of the rival", "Price below the monopoly price", "Price below last year's price"], 0, "Slide p. 46: the usual legal test is below average variable cost.")
B.mc(lo, [lo], "concept", "Under Brooke Group (1993), what must be shown besides pricing below cost?", ["A dangerous probability of recoupment", "That the rival was more efficient", "That prices were above the monopoly level", "That the firm had a patent"], 0, "Below cost plus a dangerous probability of recouping the losses (slide p. 46).")
B.tf(lo, [lo], "concept", "True or false: Predatory pricing means accepting losses now in the hope of recouping them with higher prices after the rival exits.", True, "True. Losses now, recouped later.")
B.tf(lo, [lo, "S18-05"], "concept", "True or false: Predatory pricing targets potential entrants who have not yet entered.", False, "False. It targets a rival already in the market. Potential entrants are the target of limit pricing.")
B.mc(lo, [lo], "concept", "Which law can predatory pricing violate?", ["Sherman Act §2", "The Clean Air Act", "The patent statute", "No law; it is always legal"], 0, "Slide p. 46: it can violate Sherman Act §2.")
B.mc(lo, [lo], "concept", "Why is predatory pricing hard to prove?", ["Aggressive but legal competition also produces low prices", "It never involves low prices", "Courts ignore costs", "It only happens in regulated industries"], 0, "Low prices are usually good for consumers, so courts need evidence of below-cost pricing and likely recoupment.")
B.mc(lo, [lo], "concept", "According to the textbook, which situation makes predatory pricing most likely to pay off?", ["A deep-pocketed firm against a cash-strapped rival, with little chance of re-entry", "Two equally funded rivals", "A market with very low entry barriers", "A rival that can easily shut down and reopen"], 0, "The predator must outlast the prey and then keep others out long enough to recoup.")
B.mc(lo, [lo], "concept", "After a predator drives out its rival, what can undermine the payoff?", ["The rival re-enters, or someone buys its assets and comes back", "Prices rise", "The predator gains market share", "Demand grows"], 0, "If entry returns once prices rise, the predator cannot recoup its losses.")
B.mc(lo, [lo], "apply", "A taxi company sued Uber, claiming Uber priced rides below cost to drive taxis out of San Francisco (slides p. 44). What type of claim is this?", ["Predatory pricing", "Limit pricing", "Penetration pricing", "Economies of scale"], 0, "The rivals (taxis) were already in the market, and the claim is below-cost pricing to drive them out.")
B.mc(lo, [lo], "apply", "A national chain sells hammers at $6 next to a local store when the hammers cost the chain $9, planning to raise prices once the local store closes. Classify it.", ["Predatory pricing", "Limit pricing", "Penetration pricing", "Economies of scope"], 0, "Below cost, aimed at an existing rival, with recoupment planned.")
B.mc(lo, [lo, "S18-08"], "apply", "A new food delivery app charges $0 delivery for its first year, below its cost, to get people to try it in a city where an established app dominates. Is this predatory pricing?", ["Probably not; it is penetration pricing aimed at building a customer base", "Yes, any below-cost price is predatory", "Yes, because the incumbent is hurt", "No, it is limit pricing"], 0,
     "A newcomer pricing low (even free) to win customers is penetration pricing. Predatory pricing is aimed at driving a rival out and recouping later.")
B.mc(lo, [lo, "S18-05"], "apply", "A firm cuts its price from $40 to $30. Its average variable cost is $25. An entrant has not yet come in. Is this predatory pricing?", ["No: price is above cost and the target is a potential entrant, so it is limit pricing", "Yes: any price cut is predatory", "Yes: the price fell 25%", "No: it is penetration pricing"], 0,
     "Predatory pricing requires below-cost pricing aimed at an existing rival.")
B.mc(lo, [lo], "apply", "In the textbook, Microsoft gave Internet Explorer away free and tied it to Windows to cut off Netscape. What was the outcome?", ["Microsoft lost the antitrust suit", "Microsoft was found innocent", "Netscape was found guilty of predatory pricing", "There was no lawsuit"], 0, "Microsoft lost the suit, and the EU later ruled the tying illegal.")

# ---------------- S18-07 first-mover advantage ----------------
lo = "S18-07"
B.mc(lo, [lo], "concept", "A first-mover advantage is:", ["The benefit a firm gets from moving before rivals, which lets it shape their responses", "The benefit of waiting to learn from others' mistakes", "Lower cost from producing more per period", "Lower cost from producing different products together"], 0, "Moving first lets you commit and shape rivals' best responses. Waiting is a second-mover advantage.")
B.mc(lo, [lo], "concept", "For a first move to work as a commitment, it must be:", ["Irreversible and observable to rivals", "Secret and reversible", "Cheap and flexible", "Approved by regulators"], 0, "If rivals cannot see it or it can be undone, it does not change their best response.")
B.tf(lo, [lo], "concept", "True or false: Moving first is always better than moving second.", False, "False. A second mover can free-ride on the leader's R&D and customer education and avoid its mistakes.")
B.mc(lo, [lo, "S18-04"], "concept", "How do network effects create a first-mover advantage?", ["The first network to reach critical mass locks in users even when a better one arrives", "They lower the first mover's average cost", "They make predatory pricing legal", "They let the first mover charge the monopoly price forever without entry"], 0, "Lock-in: users stay because everyone would have to switch together (eBay versus Yahoo! auctions).")
B.mc(lo, [lo, "S18-02"], "concept", "How do learning curves create a first-mover advantage?", ["The first mover has the most cumulative output and so the lowest unit cost", "The first mover produces more per period", "The first mover has more products", "The first mover pays lower wages"], 0, "Cumulative output, not size per period, moves a firm down the learning curve.")
B.mc(lo, [lo, "S18-10"], "concept", "Strategies to Crack Well-Guarded Markets advises entrants to 'close the door on the way in.' Which is one way to do that?", ["Secure scarce inputs or invest preemptively in capacity", "Raise prices immediately", "Stay in the niche forever", "Share your know-how with followers"], 0, "Also: go mainstream quickly, generate network effects, race down the experience curve.")
B.mc(lo, [lo], "concept", "Which is a source of SECOND-mover advantage?", ["Free-riding on the leader's research and customer education", "Locking in users", "Building capacity before rivals", "Securing scarce inputs"], 0, "The others are first-mover tactics.")
B.mc(lo, [lo], "apply", "Payoffs (A, B): Low/Low (30, 10), Low/High (10, 15), High/Low (20, 5), High/High (1, 2). If A moves first and B sees A's choice, what does A choose and earn?", ["High; A earns 20", "Low; A earns 10", "Low; A earns 30", "High; A earns 1"], 0,
     "If A picks Low, B picks High (15 > 10): A gets 10. If A picks High, B picks Low (5 > 2): A gets 20. A picks High.")
B.mc(lo, [lo], "apply", "In the same game (Low/Low (30, 10), Low/High (10, 15), High/Low (20, 5), High/High (1, 2)), how much is moving first worth to A compared with moving at the same time, when A earns 10?", ["10", "20", "0", "30"], 0, "A earns 20 moving first versus 10 simultaneously: a first-mover advantage of 10.")
B.mc(lo, [lo], "apply", "JetBlue bought up Embraer's manufacturing capacity for two years when it launched service with a new 100-seat jet. What was JetBlue doing?", ["Closing the door behind it by securing a scarce input", "Predatory pricing", "Creating a niche", "Limit pricing"], 0, "Locking up the scarce input kept rival airlines from copying its strategy quickly.")
B.mc(lo, [lo], "apply", "Red Bull created the U.S. energy drink niche, and then more than 150 me-too brands entered. What lesson does the reading draw?", ["Entrants should close the door on the way in by building their own barriers", "Niches are never profitable", "Red Bull should have used predatory pricing", "First movers always keep their markets"], 0, "Being first is not enough; you must build barriers once inside.")
B.mc(lo, [lo, "S18-04"], "apply", "eBay kept its auction users even when Yahoo! offered free listings. Which advantage protected eBay?", ["First-mover advantage reinforced by network effects", "Economies of scope", "Limit pricing", "A patent"], 0, "Users were locked into eBay's larger network.")
B.mc(lo, [lo], "apply", "A big tech firm spends billions to be first in a new virtual reality market, while a smaller rival waits and later launches a cheaper headset using lessons from the leader's mistakes. The smaller rival is using:", ["A second-mover advantage", "A first-mover advantage", "Limit pricing", "Economies of scale"], 0, "Waiting and learning from the leader's trial and error is a second-mover advantage (textbook Metaverse example).")
B.mc(lo, [lo], "apply", "A firm announces it 'might' build a large plant to scare off entrants, but has not signed contracts or spent any money. Why might the announcement fail?", ["It is not an irreversible commitment, so entrants may not believe it", "Announcements are illegal", "It is predatory pricing", "Entrants never pay attention"], 0, "A cheap, reversible promise does not change the entrant's expectations.")

# ---------------- S18-08 penetration pricing ----------------
lo = "S18-08"
B.mc(lo, [lo], "concept", "Penetration pricing is:", ["Charging a low price initially to gain a critical mass of customers", "Keeping price below the monopoly level to prevent entry", "Pricing below marginal cost to drive a rival out", "Charging the highest price the market will bear"], 0, "Slide p. 41 definition.")
B.mc(lo, [lo], "concept", "Penetration pricing is most useful when:", ["Strong network effects are present", "The firm has a patent", "Demand is perfectly inelastic", "The firm is a monopolist with no entrants"], 0, "Slide p. 41: useful when strong network effects are present.")
B.tf(lo, [lo], "concept", "True or false: The main goal of penetration pricing is to drive an existing rival out of the market.", False, "False. That is predatory pricing. Penetration pricing aims to win customers and reach critical mass.")
B.tf(lo, [lo], "concept", "True or false: Penetration pricing can include giving a product away for free.", True, "True. Free, or even paying users to try it, is the extreme form (Reading Quiz Q5).")
B.mc(lo, [lo], "concept", "Which firm is most likely to use penetration pricing?", ["A new entrant facing an incumbent with strong network effects", "A monopolist protected by a patent", "An incumbent facing no threat of entry", "A firm selling a commodity with no network"], 0, "It is the entrant's tool for overcoming lock-in.")
B.mc(lo, [lo, "S18-04"], "concept", "Why can a firm afford to raise prices after a successful penetration pricing campaign?", ["Once past critical mass, network effects keep users from leaving", "Antitrust law requires it", "Costs always rise", "The firm has a patent"], 0, "The network itself becomes the reason users stay.")
B.mc(lo, [lo], "concept", "Facebook appears on the S18 slides under which pricing strategy?", ["Penetration pricing", "Predatory pricing", "Limit pricing", "Peak-load pricing"], 0, "Slide p. 47: free to users, building the network.")
B.mc(lo, [lo], "apply", "A new social media app is worth little to its first users because its value depends on how many others use it. Which strategy helps it overcome established platforms' network effects?", ["Penetration pricing: a low price or free product to build a critical mass", "Premium pricing to signal quality", "Predatory pricing to drive out established platforms", "Limit pricing to discourage entry"], 0, "This is Reading Quiz Q5.")
B.mc(lo, [lo], "apply", "Yahoo! offered free auction listings to pull users from eBay and failed. What does this show?", ["Penetration pricing does not always overcome a strong incumbent network", "Penetration pricing is illegal", "eBay used predatory pricing", "Auction markets have no network effects"], 0, "eBay's network and first-mover advantage were too strong.")
B.mc(lo, [lo], "apply", "A payments app gives every new user $10 for signing up. Which strategy is this?", ["Penetration pricing", "Limit pricing", "Predatory pricing", "Economies of scope"], 0, "Paying users to join is an extreme form of penetration pricing to reach critical mass.")
B.mc(lo, [lo, "S18-05"], "apply", "An established software monopolist lowers its price to discourage a startup from entering. A different startup gives its new product away free to attract users. Which is which?", ["Monopolist: limit pricing; startup: penetration pricing", "Monopolist: penetration pricing; startup: limit pricing", "Both: predatory pricing", "Both: limit pricing"], 0, "Incumbent keeping entrants out = limit. Newcomer building a user base = penetration.")
B.mc(lo, [lo], "apply", "A video game console maker sells consoles below cost at launch to grow its user base and attract game developers. Which concept explains the low console price?", ["Penetration pricing to reach critical mass in a network market", "Predatory pricing", "Limit pricing", "Diseconomies of scale"], 0, "More players attract more developers and games, which attract more players: indirect network effects.")
B.num(lo, [lo, "S18-04"], "Each user of a new network values it at $0.20 per other user. The price to join is $40. How many users does the network need before joining is worth the price (critical mass)?", 200,
      "Value per user = 0.20 × n. Set equal to the price: 0.20n = 40, n = 200 users.", {"f": "ratio", "num": 40, "den": 0.2}, unit="users", kind="apply")
B.num(lo, [lo, "S18-04"], "Same network ($0.20 per other user). The firm uses penetration pricing and cuts the joining price to $10. What is the new critical mass?", 50,
      "0.20n = 10, n = 50 users. A lower price shrinks the critical mass the network has to reach.", {"f": "ratio", "num": 10, "den": 0.2}, unit="users", kind="apply")

# ---------------- S18-09 common barriers ----------------
lo = "S18-09"
B.mc(lo, [lo], "concept", "Which of these is NOT one of the structural barriers on the S18 slides?", ["Buyer price sensitivity", "Learning curves", "Brand and reputation", "Patents and other legal barriers"], 0, "Buyer price sensitivity is about demand, not about an entrant's costs or share (Reading Quiz Q3).")
B.mc(lo, [lo], "concept", "According to the reading, which three barriers kept newcomers out of the soft drinks industry?", ["Brands, bottling and distribution capabilities, and shelf space", "Patents, network effects and learning curves", "Government licenses, tariffs and quotas", "Economies of scope, limit pricing and predatory pricing"], 0, "Strategies to Crack Well-Guarded Markets, soft drinks example.")
B.tf(lo, [lo], "concept", "True or false: Capital requirements can be a barrier to entry.", True, "True. Reading Quiz Q3 lists capital requirements with economies of scale and network effects as common barriers.")
B.mc(lo, [lo], "concept", "Why do profitable industries attract entry in the first place?", ["High profits signal that entrants could earn more than elsewhere", "Profitable industries have no barriers", "Incumbents invite entrants", "Entry is always cheaper there"], 0, "Money attracts money: the most profitable industries had almost five times as many entrants as the average industry.")
B.mc(lo, [lo], "concept", "Patents are a barrier to entry because they:", ["Legally prevent others from making the protected product for a period", "Lower the incumbent's average cost", "Create network effects", "Make predatory pricing legal"], 0, "A legal barrier: entrants cannot copy the product.")
B.mc(lo, [lo], "apply", "In the razor case, Gillette spent $200 million marketing one razor. Dollar Shave Club entered with a $20,000 YouTube video and online subscriptions. Which barrier did DSC get around?", ["Brand and reputation, plus retail shelf space", "Patents", "Network effects", "Learning curves"], 0, "Gillette's brand and store distribution were the barrier; DSC used cheap online marketing and direct delivery.")
B.mc(lo, [lo], "apply", "A new airline cannot get landing slots at a busy airport because slots are allocated by regulators. Which barrier is this?", ["Legal or government barrier", "Economies of scope", "Learning curve", "Penetration pricing"], 0, "Government control of access is a legal barrier.")
B.mc(lo, [lo], "apply", "A semiconductor startup must spend $20 billion on a fabrication plant before selling its first chip. Which barrier is most directly at work?", ["Capital requirements", "Network effects", "Brand", "Limit pricing"], 0, "The huge up-front investment itself keeps entrants out (and the plant only pays off at huge volume, adding scale).")
B.mc(lo, [lo], "apply", "Virgin Cola's U.S. launch included Richard Branson driving a tank through a wall of cans in Times Square, yet it never passed 1% of U.S. cola. What does the S18 slide on brand and reputation show?", ["Incumbent brands and shelf space can defeat even a heavily promoted head-on entrant", "Advertising always wins market share", "Virgin used limit pricing", "Cola has strong network effects"], 0, "Coke and Pepsi's brands and grip on shelf space held.")
B.num(lo, [lo, "S18-04"], "From the exercise (Table 2), Meta's 2021 Q4 profit per user was about $5.99 and Twitter's was about $0.06. What was Meta's profit advantage per user?", 5.93,
      "5.99 - 0.06 = $5.93 per user for the quarter. From 2017 to 2021 the advantage over Twitter averaged about $5.17.", {"f": "diff", "x1": 0.061, "x2": 5.989}, unit="$", kind="apply")

# ---------------- S18-10 circumventing barriers ----------------
lo = "S18-10"
B.mc(lo, [lo], "concept", "What common theme did Bryce and Dyer find among successful entrants into profitable markets?", ["Indirect assault: avoid the incumbent's strongholds", "Frontal attack with heavy advertising", "Acquiring an incumbent", "Matching the leader's business model at a lower price"], 0, "Smart newcomers refuse to challenge incumbents on their terms and turf.")
B.mc(lo, [lo], "concept", "Which combination does the reading call arguably the most powerful?", ["Reconfigure the value chain and create a niche", "Leverage existing assets and create a niche", "Leverage existing assets and reconfigure the value chain", "All three together"], 0, "A low-cost model aimed at customers incumbents ignore keeps the entrant off their radar (Skype, Usana).")
B.tf(lo, [lo], "concept", "True or false: According to the reading, successful entrants usually combine at least two of the three strategies.", True, "True. The magic lies in their combination.")
B.mc(lo, [lo], "concept", "Why does the reading say acquisitions are a risky way into profitable markets?", ["Buyers pay a premium (about 30%) for the target's present and future profits", "Acquisitions are illegal", "Acquired firms lose their brands", "Acquisitions create network effects"], 0, "The buyer pays for the profit streams up front, so shareholders often lose value.")
B.mc(lo, [lo], "concept", "What does 'create a market niche' mean in the reading?", ["Develop offerings with features that do not initially appeal to mainstream customers but attract a fringe segment", "Copy the leader's best product", "Use your existing shelf space", "Change the sequence of activities that deliver value"], 0, "The other choices describe copying, leveraging assets and reconfiguring the value chain.")
B.mc(lo, [lo], "apply", "Red Bull entered U.S. soft drinks selling a premium energy drink in bars and nightclubs before moving into stores. Which strategy did it start with?", ["Create a market niche", "Leverage existing assets", "Directly attack the market leader", "Predatory pricing"], 0, "A fringe segment (club-goers) that mainstream cola buyers and so Coke and Pepsi did not care about.")
B.mc(lo, [lo], "apply", "McDonald's put Redbox DVD rental kiosks in its restaurants. Which strategy is this primarily?", ["Leverage existing assets", "Create a market niche", "Reconfigure the value chain", "Limit pricing"], 0, "It used excess capacity in stores it already had, its locations and its reputation.")
B.mc(lo, [lo], "apply", "Walmart teamed with Cott to make Sam's Choice soda, bottled centrally and shipped through Walmart's own distribution centers, sold only in Walmart. Which combination is this?", ["Leverage existing assets and reconfigure the value chain", "Create a niche and reconfigure the value chain", "Leverage existing assets and create a niche", "Directly attack the market leader"], 0, "Walmart's shelf space and distribution (assets) plus a hub-and-spoke system that bypassed the leaders' delivery model (value chain).")
B.mc(lo, [lo], "apply", "Skype let people make cheap calls over the internet, attracting cost-sensitive users who did not mind lower quality. Which combination is this?", ["Reconfigure the value chain and create a niche", "Leverage existing assets and create a niche", "Leverage existing assets only", "Directly attack the market leader"], 0, "New technology changed how calls are delivered, aimed first at a fringe of price-sensitive users.")
B.mc(lo, [lo], "apply", "Microsoft's Xbox attacked Sony and Nintendo head on and lost about $4.5 billion in five years. Jakks Pacific sold cheap plug-and-play games for kids. What does the contrast show?", ["Indirect entry beats a frontal attack", "Bigger firms always win", "Video games have no barriers", "Niche products cannot be profitable"], 0, "Jakks avoided the leaders' strongholds and earned about 15% operating margins.")
B.mc(lo, [lo], "apply", "TikTok grew into a major competitor to Meta by building a short-video feed driven by a recommendation algorithm instead of a friend network, aimed first at young users. Which strategies from the reading fit best?", ["Reconfigure the value chain and create a niche", "Leverage existing assets only", "Directly attack the market leader", "Limit pricing"], 0,
     "A different way of delivering content (algorithm rather than friend graph) plus a young niche. ByteDance also leveraged technology from its other apps.")
B.mc(lo, [lo], "apply", "Meta launched Threads in 2023 by letting Instagram users sign up with one tap and bring their followers. Which strategy is this primarily?", ["Leverage existing assets", "Create a market niche", "Reconfigure the value chain", "Predatory pricing"], 0, "It used Instagram's existing user base and social graph to jump-start a new network.")

